import {debounce,focusPage,preserveFocus,installAccessibility} from './p3.js';
import {icon} from './icons.js';
import {cleanupMotion,cleanupDashboardMotion,enhanceMotion} from './motion.js';
import {events} from './data.js';
import {featurePages as p0Pages,renderFeature,stopFeature,openReview} from './features.js';
import {p2Pages,renderP2,stopP2} from './p2.js';
const featurePages=[...p0Pages,...p2Pages];
import {request,setToken,retryRemaining} from './api.js';
import {summaryCards,latestCards,freshnessPanel,renderSources,stopSources,errorMessage} from './p1.js';
let reports=[], locations=[], page='Overview',period=7,location='',event='',status='',search='',offset=0,utc=false,staff=false,role=null,loading=false,error='',zoom=1,lastSync=null;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={Overview:icon('overview'),'Event explorer':icon('explore'),Analytics:icon('analytics'),'Review queue':icon('review'),'Data sources':icon('source'),Settings:icon('settings')};
const badge=r=>`<span class="badge ${esc(r.status)}">${r.status==='verified'?'Verified by reviewer':r.status==='pending'?'Pending review':'Rejected'}</span>`;
const time=t=>t?new Date(t).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',...(utc?{timeZone:'UTC'}:{})}):'–';
const reportLimit=6;
let reportPage={total:0,limit:reportLimit,offset:0}, summary=null, latest=null, eventData=null, dayData=null, mapData=null;
let summaryState='idle',latestState='idle',eventState='idle',dayState='idle',mapState='idle',locationError=null;
const sectionErrors={};
function filtered(){return reports.filter(r=>(staff||r.status==='verified')&&(!search||`${r.description} ${r.location_name} ${r.id}`.toLowerCase().includes(search.toLowerCase())));}
function statePanel(name,state,error){return `<section class="panel p1-state"><h2>${esc(name)}</h2>${state==='loading'||state==='idle'?'<p role="status">Loading…</p>':`<p role="alert">${esc(errorMessage(error))}</p>${error.status===403?'':`<button class="button" data-reload data-path="${esc(error.path||'')}">Retry</button>`}`}</section>`;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function render(){applySearch.cancel();scheduleFilters.cancel();stopP2();stopFeature();cleanupMotion(); const pending=staff?summary?.reports?.by_status?.pending:undefined;
$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="Monsoon overview"><span class="brandmark">${icon('logo')}</span>monsoon<span class="brand-dot">.</span></a><div class="workspace"><span class="workspace-icon">M</span><div>Weather intelligence<small>India observatory</small></div><span>⌄</span></div><p class="nav-label">WORKSPACE</p><div class="p0-navigation"><nav>${['Overview','Event explorer','Analytics','Weather explorer','Weather trends','Location comparison','Events analytics','News feed','Anomalies','About & data','Submit report','Track report','Staff access'].map(nav).join('')}</nav><p class="nav-label">ADMINISTRATION</p><nav>${(role==='admin'?['Review queue','Ingestion monitor','Data sources']:staff?['Review queue','Data sources']:['Data sources']).map(nav).join('')}</nav></div><div class="sidebar-bottom"><div class="network"><span class="dot"></span>API connection<small>Refreshes every 30 seconds</small></div><button data-page="Settings" aria-label="Settings and connection" class="nav-button">${icon('settings')} <span>Settings & connection</span></button><div class="profile"><span class="avatar">${staff?'AK':'GU'}</span><div>${staff?'Analyst workspace':'Public workspace'}<small>${staff?'Staff session':'Verified reports only'}</small></div><button id="session" title="Change session" aria-label="Change staff session">↗</button></div></div></aside><div class="scroll-progress" aria-hidden="true"></div><div class="main"><header class="topbar"><div><span class="crumb">Workspace</span><span class="slash">/</span>${esc(page)}</div><div class="top-actions"><span class="mode">Backend API</span><button id="theme-toggle" class="theme-toggle" aria-label="Toggle dark and light mode" aria-pressed="${document.documentElement.dataset.theme==='light'}"><span aria-hidden="true">◐</span><span class="theme-label">${document.documentElement.dataset.theme==='light'?'Dark':'Light'}</span></button><button id="refresh" aria-label="Refresh data">${icon('refresh')}</button><span class="avatar small">${staff?'AK':'GU'}</span></div></header><main id="workspace-main" tabindex="-1">${page==='Overview'?'<section id="signal-hero" class="signal-hero" aria-label="Monsoon observatory"></section>':`<div class="page-heading"><div><h1>${featurePages.includes(page)?esc(page):page==='Overview'?'A clearer view of the weather.':page==='Review queue'?'Every report deserves a closer look.':page==='Analytics'?'Patterns beyond the forecast.':page==='Event explorer'?'Follow the events on the ground.':page==='Data sources'?'Know where your data comes from.':'Your observation workspace.'}</h1><p>${page==='Overview'?'Monitor events, connect the signals, and find the reports you can trust.':page==='Review queue'?'Review evidence and make the final call. Verification requires a human review of the evidence.':page==='Data sources'?'Source provenance, freshness, and ingestion at a glance.':'Explore weather intelligence with context and traceable sources.'}</p></div>${featurePages.includes(page)||['Data sources','Settings','Staff access'].includes(page)?'':`<button class="button" id="export">${icon('down')} <span>Export page</span></button>`}</div>`}${featurePages.includes(page)?'<div id="p0-content"></div>':(page==='Settings'||page==='Staff access')?settings():page==='Data sources'?sources():`<div id="dashboard-region">${dashboardContent()}</div>`}<footer><span>monsoon <span class="footer-dot">/</span> Weather intelligence, with provenance.</span><span>${lastSync?'Last refreshed '+lastSync.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}):'Awaiting data'} · 30s refresh</span></footer></main></div>`;
function nav(n){return `<button class="nav-button ${page===n?'active':''}" data-page="${n}" aria-label="${n}" aria-current="${page===n?'page':'false'}"><span class="nav-icon">${icons[n]||icon(n==='Submit report'?'review':n==='Track report'?'explore':n==='Ingestion monitor'?'source':n==='Staff access'?'settings':'analytics')}</span><span class="nav-label-roll"><span>${n}</span><span aria-hidden="true">${n}</span></span>${n==='Review queue'&&pending!==undefined?`<span class="count">${pending}</span>`:''}${page===n?`<span class="nav-arrow">${icon('arrow')}</span>`:''}</button>`;}
bind();enhanceMotion(page);if(featurePages.includes(page))startFeature();if(page==='Data sources')loadSources();updateExpiry();}

function dashboardContent(){const data=filtered();const summaryView=summaryState==='success'?metrics():statePanel('Summary',summaryState,sectionErrors.summary);const eventView=eventState==='success'?distribution():statePanel('Event breakdown',eventState,sectionErrors.events);return `${filters()}${locationError?`<p role="alert">${esc(errorMessage(locationError))}</p>`:''}${summaryView}${page==='Overview'?`${latestState==='success'?latestCards(latest,locations,time,location):statePanel('Latest weather',latestState,sectionErrors.latest)}${summaryState==='success'?freshnessPanel(summary.sources||[],time):''}<div class="visual-grid">${mapState==='success'?map():statePanel('Report locations',mapState,sectionErrors.map)}${eventView}</div>`:page==='Analytics'?`<div class="visual-grid">${dayState==='success'?trend():statePanel('Reports over time',dayState,sectionErrors.days)}${eventView}</div>`:''}${loading?'<section class="panel empty" role="status">Loading reports…</section>':error?statePanel('Reports','error',error):table(data)}`;}
function renderDashboard({focusLocation,focusId}={}){const region=$('#dashboard-region');if(!region)return;const restoreFocus=preserveFocus(region);const chartOpen=!!region.querySelector('.trend details[open]');const y=window.scrollY;cleanupDashboardMotion();region.innerHTML=dashboardContent();if(chartOpen&&region.querySelector('.trend details'))region.querySelector('.trend details').open=true;const count=document.querySelector('.nav-button[data-page="Review queue"] .count');if(count)count.textContent=summary?.reports?.by_status?.pending??'–';bind();enhanceMotion(page,{dashboardOnly:true});const sync=document.querySelector('footer>span:last-child');if(sync)sync.textContent=(lastSync?'Last refreshed '+lastSync.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}):'Awaiting data')+' · 30s refresh';window.scrollTo({top:y,behavior:'instant'});if(focusLocation)document.querySelector('[data-loc="'+focusLocation+'"]')?.focus({preventScroll:true});else if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});else restoreFocus();}

function filters(){return `<div class="section-label"><h2>The observatory.</h2>${page==='Overview'?`<button class="button" id="export">${icon('down')} Export page</button>`:''}</div><section class="filters" aria-label="Report filters"><div class="period">${[1,7,30].map(n=>`<button data-period="${n}" aria-pressed="${period===n}" class="${period===n?'selected':''}">${n===1?'24 hours':n+' days'}</button>`).join('')}</div><label><select id="location" aria-label="Location"><option value="">All locations</option>${locations.map(l=>`<option value="${l.id}" ${String(l.id)===location?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label><label><select id="event" aria-label="Event type"><option value="">All events</option>${Object.entries(events).map(([k,v])=>`<option value="${k}" ${event===k?'selected':''}>${v}</option>`).join('')}</select></label>${staff?`<label><select id="status" aria-label="Verification status"><option value="">All statuses</option>${['verified','pending','rejected'].map(v=>`<option ${status===v?'selected':''} value="${v}">${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label>`:''}<button class="text-button" id="reset">Reset filters</button><span class="filter-date">${new Date(Date.now()-period*86400000).toLocaleDateString('en-IN',{day:'numeric',month:'short'})} – ${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</span></section>`;}
function metrics(){if(page==='Overview')return `${summaryCards(summary,staff)}${summary.reports?.total===0&&(summary.weather?.records_by_kind?.observation??summary.weather?.record_counts?.observation)===0&&(summary.weather?.records_by_kind?.forecast??summary.weather?.record_counts?.forecast)===0?'<p class="empty" role="status">No weather records or reports in this period.</p>':''}`;const counts=summary.reports?.by_status||{};const cards=[['Total reports',summary.reports?.total,'Selected period and location · all event types'],['Verified reports',counts.verified,'Verified by reviewer'],['Locations with weather',summary.weather?.locations_with_data,'Selected period and location']];if(staff&&counts.pending!==undefined)cards.push(['Awaiting review',counts.pending,'Pending review']);return `<section class="metrics">${cards.map(([label,note,caption])=>`<article><div>${label}</div><strong>${esc(note??'–')}</strong><small>${caption}</small></article>`).join('')}</section>`;}
function map(){const groups=locations.map(l=>{const counts=mapData.items.find(item=>String(item.location.id)===String(l.id))?.report_counts||{};return {...l,count:status?counts[status]||0:Object.values(counts).reduce((total,n)=>total+n,0)};}).filter(l=>l.count||String(l.id)===location);return `<section class="panel map-panel"><div class="panel-head"><div><h2>Weather on the ground</h2><p>All event types · selected period · backend counts</p></div><span class="badge verified"><span class="dot"></span>${groups.length} locations</span></div><div class="map-stage"><svg class="geo" viewBox="0 0 760 380" role="group" aria-label="Schematic geographic locator of Indian cities; not a boundary map"><defs><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="currentColor" stroke-width=".4"/></pattern></defs><rect width="760" height="380" fill="url(#grid)"/><g class="contours"><path d="M-30 300Q80 160 180 220T400 200T780 90M-30 325Q90 170 190 240T420 220T780 115M-30 350Q100 190 200 260T440 240T780 140M-30 375Q110 210 210 280T460 260T780 165M-30 400Q120 230 220 300T480 280T780 190M-30 425Q130 250 230 320T500 300T780 215"/></g><g transform="translate(${380-380*zoom} ${190-190*zoom}) scale(${zoom})"><path class="land" d="M285 20L326 37L347 65L368 69L376 91L411 97L434 122L476 131L503 128L523 110L557 112L551 137L522 156L495 151L478 173L446 170L421 190L406 212L384 227L366 257L353 280L337 316L325 332L312 317L301 288L287 266L279 236L267 213L247 184L228 174L213 149L236 139L245 112L264 100L273 78L264 56Z"/><path class="internal" d="M273 78L330 100L376 91M245 112L304 138L347 111L411 97M236 139L290 165L334 148L376 173L434 122M267 213L315 202L334 148M287 266L333 244L384 227M301 288L353 280M290 165L315 202L333 244M376 173L366 219L406 212"/>${groups.map(l=>{const x=250+(l.longitude-72)*14,y=70+(30-l.latitude)*12;return `<g class="marker ${String(l.id)===location?'is-selected':''}" data-loc="${l.id}" tabindex="0" role="button" aria-pressed="${String(l.id)===location}" aria-label="Filter ${esc(l.name)}, ${l.count} reports"><circle cx="${x}" cy="${y}" r="25" class="selection-ring"/><circle cx="${x}" cy="${y}" r="20" class="halo"/><circle cx="${x}" cy="${y}" r="10"/><text x="${x}" y="${y+4}" class="marker-count">${l.count}</text><text x="${l.name==='Bengaluru'?x-16:x+16}" y="${y+4}" text-anchor="${l.name==='Bengaluru'?'end':'start'}" class="city-label">${esc(l.name)}</text></g>`;}).join('')}</g></svg><span class="sea sea-left">ARABIAN<br>SEA</span><span class="sea sea-right">BAY OF<br>BENGAL</span><div class="map-key"><span class="dot"></span> Report cluster <span>Size shows activity</span></div><div class="zoom"><button id="zoom-in" aria-label="Zoom in">+</button><button id="zoom-out" aria-label="Zoom out">−</button></div><span class="map-disclaimer">Schematic locator · Not a boundary map</span></div><div class="map-footer"><div class="map-location"><span> ${location?esc(locations.find(l=>String(l.id)===location)?.name):'India'} <span class="muted">/ ${reportPage.total} reports in list</span></span>${location?'<button id="clear-location" class="location-clear" aria-label="Clear selected location">Clear selection ×</button>':''}</div><button class="text-button" data-page="Event explorer">Explore reports ${icon('arrow')}</button></div></section>`;}
function distribution(){const counts=eventData.items.map(item=>({k:item.key,v:events[item.key]||item.key,n:item.count})).filter(item=>item.n).sort((a,b)=>b.n-a.n),total=counts.reduce((sum,item)=>sum+item.n,0);let stop=0;const fills=['var(--accent)','var(--chart-mid)','var(--chart-soft)','var(--line)'];const segments=counts.map((c,i)=>{const start=stop;stop+=c.n/(total||1)*100;return `${fills[Math.min(i,3)]} ${start}% ${stop}%`;}).join(',');return `<section class="panel distribution"><div class="panel-head"><div><h2>Event breakdown</h2><p>Reports by event type</p></div></div><div class="donut" role="img" aria-label="${total} citizen reports. Counts by event type follow below." style="background:${total?`conic-gradient(${segments})`:'var(--line)'}"><div><strong>${total}</strong><span>total events</span></div></div><div class="event-bars">${counts.map((c,i)=>`<button data-event="${esc(c.k)}"><span class="legend-dot tone-${i}"></span><span>${esc(c.v)}</span><strong>${c.n}</strong><span class="muted">${Math.round(c.n/total*100)}%</span></button>`).join('')||'<p>No events in this selection.</p>'}</div><div class="distribution-footer">Counts from backend analytics <span>✧</span></div></section>`;}
function table(data){const list=data;return `<section class="panel reports"><div class="panel-head"><div><h2>${page==='Review queue'?'Moderation queue':'Latest event reports'} <span class="inline-count">${reportPage.total}</span></h2><p>${page==='Review queue'?'Oldest reports first. Open a report to review evidence.':'Citizen reports in the selected period.'}</p></div><div class="table-tools"><label class="search">${icon('search')} <input id="search" placeholder="Search this page…" aria-label="Search the current page only" value="${esc(search)}"></label><button id="utc" class="button" aria-label="${utc?'UTC':'Local time'}: toggle table time zone" aria-pressed="${utc}">${utc?'UTC':'Local time'}</button></div></div><div class="table-scroll"><table><thead><tr><th>Event</th><th>Location</th><th>Event time</th><th>Severity</th><th>Verification</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${list.map(r=>`<tr><td><button class="report-link" data-report="${esc(r.id)}"><span class="weather-icon">${icon(r.event_type==='heavy_rain'?'rain':r.event_type==='heatwave'?'sun':'wind')}</span><span>${esc(events[r.event_type]||r.event_type)}<small>${esc(r.id)} · Citizen report</small></span></button></td><td>${esc(r.location?.name||r.location_name||'Unassigned')}<small>India</small></td><td>${time(r.event_time)}<small>${utc?'UTC':Intl.DateTimeFormat().resolvedOptions().timeZone}</small></td><td><span class="severity ${esc(r.severity)}">● ${esc(r.severity||'Not specified')}</span></td><td>${badge(r)}</td><td><button data-report="${esc(r.id)}" aria-label="Open report ${esc(r.id)}">${icon('diagonal')}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No reports match these filters on this page.<br><button id="empty-reset">Clear filters</button></div></td></tr>'}</tbody></table></div><div class="table-footer"><span>${reportPage.total?reportPage.offset+1:0}–${Math.min(reportPage.offset+reports.length,reportPage.total)} of ${reportPage.total} reports${search?` · ${list.length} matches on this page`:""}</span><div><button id="prev" ${reportPage.offset===0?'disabled':''}>← Previous</button><button id="next" ${reportPage.offset+reportPage.limit>=reportPage.total?'disabled':''}>Next →</button></div></div></section>`;}
function trend(){const days=dayData.items.map(item=>({label:item.key,n:item.count}));const max=Math.max(1,...days.map(d=>d.n));return `<section class="panel trend"><div class="panel-head"><div><h2>Reports over time</h2><p>Daily report counts · All selected events</p></div></div>${days.length?'':'<p class="empty" role="status">No reports in this period.</p>'}<div class="bar-chart">${days.map(d=>`<div class="bar-column"><span>${d.n}</span><div style="height:${d.n/max*190}px" title="${esc(d.label)}: ${esc(d.n)} reports"></div><small>${period<=7?esc(d.label):''}</small></div>`).join('')}</div><details><summary>Daily report counts</summary><button id="chart-utc" class="button" type="button" aria-pressed="${utc}">Time zone: ${utc?'UTC':'Local time'}</button><div class="table-scroll"><table><thead><tr><th>Bucket start (${utc?'UTC':'Local time'})</th><th>Report count</th></tr></thead><tbody>${days.map(d=>`<tr><td>${time(`${d.label}T00:00:00Z`)}</td><td>${esc(d.n??'–')}</td></tr>`).join('')||'<tr><td colspan="2">No report counts returned.</td></tr>'}</tbody></table></div></details><p class="chart-caption">${dayData.items.reduce((sum,item)=>sum+item.count,0)} reports over ${period} days. Counts from backend analytics; weather measurements are separate.</p></section>`;}
function sources(){return `<section class="panel"><div class="panel-head"><div><h2>Connected data sources</h2><p>Source status from your backend.</p></div></div><div id="source-content"><div class="empty">Loading source status…</div></div></section><div class="trust-note"><h2>A source is not a verdict.</h2><p>Open-Meteo data is model-derived, not station readings or official observations. Citizen reports are only verified after human review. News items are not verified observations.</p></div>`;}
function settings(){return `<section class="panel settings"><h2>Connection & session</h2><p>The frontend uses your configured backend API.</p><dl><dt>Data mode</dt><dd>Live API</dd><dt>API base URL</dt><dd>${esc(window.MONSOON_CONFIG.API_BASE_URL)}</dd><dt>Refresh interval</dt><dd>30 seconds</dd><dt>Session</dt><dd>${restoring?'Restoring session…':staff?esc(role):'Public'}</dd><dt>Session expiry</dt><dd id="session-expiry">${sessionExpiryText()}</dd></dl><p>Connection configuration lives in <code>dist/config.js</code>. Set API_BASE_URL to your backend origin.</p><p id="session-notice" role="status">${esc(sessionNotice)}</p>${restoreFailed?'<button id="restore-session" class="button">Retry session restore</button>':''}<button id="login" class="primary" ${restoring?'disabled':''}>${staff?'Sign out':'Staff login'}</button></section>`;}
const applySearch=debounce(()=>renderDashboard(),300);
const scheduleFilters=debounce(()=>load(),300);
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{const changed=page!==b.dataset.page;controller?.abort();stopSources();featureGeneration++;page=b.dataset.page;offset=0;search='';render();if(['Overview','Event explorer','Analytics'].includes(page))load();if(changed){focusPage();window.scrollTo({top:0,behavior:'instant'});}});$('.brand').onclick=e=>{e.preventDefault();controller?.abort();stopSources();page='Overview';offset=0;render();load();window.scrollTo({top:0,behavior:'instant'});}; document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=+b.dataset.period;offset=0;renderDashboard();load();});['location','event','status'].forEach(id=>{if($('#'+id))$('#'+id).onchange=e=>{if(id==='location')location=e.target.value;if(id==='event')event=e.target.value;if(id==='status')status=e.target.value;offset=0;renderDashboard();scheduleFilters();};});
['reset','empty-reset'].forEach(id=>{if($('#'+id))$('#'+id).onclick=()=>{location=event=status=search='';offset=0;renderDashboard();load();};});
document.querySelectorAll('[data-loc]').forEach(b=>{const select=()=>{const id=b.dataset.loc;location=location===id?'':id;offset=0;renderDashboard({focusLocation:id});load();};b.onclick=select;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{event=b.dataset.event;offset=0;renderDashboard();load();});
if($('#search')){const input=$('#search');input.oninput=e=>{search=e.target.value;offset=0;if(!e.isComposing)applySearch();};input.oncompositionend=()=>{search=input.value;applySearch();};}
document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>openReport(b.dataset.report));
if($('#prev'))$('#prev').onclick=()=>{offset=Math.max(0,reportPage.offset-reportPage.limit);load({reportOnly:true,focusId:'prev'});};if($('#next'))$('#next').onclick=()=>{offset=reportPage.offset+reportPage.limit;load({reportOnly:true,focusId:'next'});};['utc','chart-utc'].forEach(id=>{if($('#'+id))$('#'+id).onclick=()=>{utc=!utc;renderDashboard({focusId:id});};});
if($('#zoom-in'))$('#zoom-in').onclick=()=>{zoom=Math.min(1.8,zoom+.2);renderDashboard({focusId:'zoom-in'});};if($('#zoom-out'))$('#zoom-out').onclick=()=>{zoom=Math.max(.8,zoom-.2);renderDashboard({focusId:'zoom-out'});};
if($('#clear-location'))$('#clear-location').onclick=()=>{location='';offset=0;renderDashboard();load();};$('#theme-toggle').onclick=()=>{const light=document.documentElement.dataset.theme!=='light';document.documentElement.dataset.theme=light?'light':'dark';$('#theme-toggle').setAttribute('aria-pressed',String(light));$('.theme-label').textContent=light?'Dark':'Light';try{localStorage.setItem('monsoon-theme',light?'light':'dark');}catch{/* Theme storage may be unavailable. */}};$('#refresh').onclick=()=>featurePages.includes(page)?startFeature():page==='Data sources'?loadSources():['Settings','Staff access'].includes(page)?render():load();if($('#retry'))$('#retry').onclick=()=>load();if($('#export'))$('#export').onclick=exportCSV;$('#session').onclick=login;if($('#login'))$('#login').onclick=login;if($('#restore-session')){$('#restore-session').onclick=boot;retryButton($('#restore-session'),'/auth/me');}document.querySelectorAll('[data-reload]').forEach(button=>{button.onclick=()=>load();retryButton(button,button.dataset.path);});if($('#export'))$('#export').disabled=loading||!!error;}
function openReport(id){openReview(id,featureContext(),()=>load());}
function exportCSV(){const rows=[['id','event_type','location','event_time','severity','status'],...filtered().map(r=>[r.id,r.event_type,r.location?.name,r.event_time,r.severity,r.status])];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='monsoon-reports.csv';a.click();URL.revokeObjectURL(url);toast('Current report page exported');}
let expiryTimer, loginOpen=false, expiresAt=null, restoring=false, restoreFailed=false, sessionNotice='',restoreController,sessionGeneration=0;
const sessionKey='monsoon-session';
function sessionExpiryText(){return expiresAt?`${new Date(expiresAt).toLocaleString('en-IN')} · ${Math.max(0,Math.ceil((expiresAt-Date.now())/1000))}s remaining`:'No active staff session';}
function updateExpiry(){if($('#session-expiry'))$('#session-expiry').textContent=sessionExpiryText();}
function retryButton(button,path){const label=button.textContent;const tick=()=>{if(!button.isConnected)return;const remaining=retryRemaining(path);button.disabled=remaining>0;button.textContent=remaining?`${label} (${remaining}s)`:label;if(remaining)setTimeout(tick,1000);};tick();}
function armExpiry(){clearTimeout(expiryTimer);expiryTimer=setTimeout(()=>window.dispatchEvent(new Event('session-expired')),Math.max(0,expiresAt-Date.now()));}
function rememberSession(response){setToken(response.access_token);role=response.user.role;staff=true;expiresAt=Date.now()+response.expires_in*1000;try{sessionStorage.setItem(sessionKey,JSON.stringify({access_token:response.access_token,expires_at:expiresAt}));}catch{/* Memory-only sessions still work if storage is disabled. */}armExpiry();}

function featureContext(){return {locations,staff,role,utc:()=>utc,toggleUTC:()=>{utc=!utc;}};}
let featureGeneration=0;
async function startFeature(){
  const target=page,generation=++featureGeneration;
  const root=$('#p0-content');if(!root)return;
  stopFeature();stopP2();root.innerHTML=(page==='Anomalies'?'<p class="p2-disclaimer" role="note">Statistical flag only. Not an official warning.</p>':'')+'<p role="status">Loading locations…</p>';
  try{
    if(!locations.length&&['Weather explorer','Weather trends','Review queue','Events analytics','Anomalies'].includes(page)){const response=await request('/locations');locations=response.items;}
    if(page===target&&generation===featureGeneration){if(p2Pages.includes(page))renderP2(page,featureContext());else renderFeature(page,featureContext());}
  }catch(e){if(page!==target||generation!==featureGeneration)return;root.textContent=`${e.message}${e.request_id?' · Request ID: '+e.request_id:''}`;if(page==='Anomalies')root.insertAdjacentHTML('afterbegin','<p class="p2-disclaimer" role="note">Statistical flag only. Not an official warning.</p>');if(e.status!==403&&e.status!==401){const button=document.createElement('button');button.className='button';button.textContent='Retry';button.onclick=startFeature;root.append(button);let seconds=e.retry_after||0;const tick=()=>{if(!button.isConnected)return;button.disabled=seconds>0;button.textContent=seconds?`Retry (${seconds--}s)`:'Retry';if(button.disabled)setTimeout(tick,1000);};tick();}}
}
function clearSession(){restoreController?.abort();sessionGeneration++;restoring=false;error=null;loading=false;Object.keys(sectionErrors).forEach(key=>delete sectionErrors[key]);controller?.abort();clearTimeout(expiryTimer);setToken(null);staff=false;role=null;expiresAt=null;reports=[];summary=latest=eventData=dayData=mapData=null;summaryState=latestState=eventState=dayState=mapState='idle';reportPage={total:0,limit:reportLimit,offset:0};offset=0;status='';stopFeature();stopP2();stopSources();featureGeneration++;restoreFailed=false;try{sessionStorage.removeItem(sessionKey);}catch{/* Storage may be disabled. */}}
function login(){
  if(staff){clearSession();sessionNotice='Signed out.';page='Overview';render();load();toast('Signed out.');return;}
  if(loginOpen)return;loginOpen=true;
  const dlg=$('#detail');if(dlg.open)dlg.close();
  dlg.innerHTML='<div class="dialog-head"><h2>Staff login</h2><button id="close" aria-label="Close login">×</button></div><form class="dialog-body p0-form" id="login-form"><label class="p0-field">Email<input name="email" type="email" required autocomplete="username"></label><label class="p0-field">Password<input name="password" type="password" required autocomplete="current-password"></label><button class="primary">Sign in</button><p id="login-error" role="alert"></p></form>';
  dlg.addEventListener('close',()=>{loginOpen=false;},{once:true});dlg.showModal();$('#close').onclick=()=>dlg.close();
  const button=dlg.querySelector('form button');
  function cooldownLogin(){const remaining=retryRemaining('/auth/login','POST');button.disabled=remaining>0;button.textContent=remaining?`Sign in (${remaining}s)`:'Sign in';if(remaining&&button.isConnected)setTimeout(cooldownLogin,1000);}
  cooldownLogin();
  $('#login-form').onsubmit=async e=>{e.preventDefault();button.disabled=true;const f=new FormData(e.target);try{const r=await request('/auth/login',{method:'POST',body:Object.fromEntries(f)});rememberSession(r);restoreFailed=false;sessionNotice='';dlg.close();page='Overview';offset=0;render();load();toast('Signed in. Session expires at '+new Date(expiresAt).toLocaleTimeString('en-IN'));}catch(error){const node=$('#login-error');if(node)node.textContent=`Unable to sign in. Check your credentials or try again later.${error.request_id?' Request ID: '+error.request_id:''}`;}finally{cooldownLogin();}};
}
let controller,loadGeneration=0,windowRange=null;
async function load({reportOnly=false,focusId}={}){
  controller?.abort();const active=new AbortController();controller=active;const generation=++loadGeneration;
  if(!reportOnly||!windowRange)windowRange={from:new Date(Date.now()-period*86400000).toISOString(),to:new Date().toISOString()};
  const base=new URLSearchParams(windowRange);if(location)base.set('location_id',location);
  const reportQuery=new URLSearchParams(base);if(event)reportQuery.set('event_type',event);if(staff)reportQuery.set('status',status||'all');reportQuery.set('sort','-event_time');reportQuery.set('limit',reportLimit);reportQuery.set('offset',offset);
  loading=true;error=null;reports=[];
  if(!reportOnly){summaryState=latestState=eventState=dayState=mapState='loading';summary=latest=eventData=dayData=mapData=null;}
  renderDashboard();
  const jobs=[['reports',`/reports?${reportQuery}`]];
  if(!locations.length)jobs.push(['locations','/locations']);
  if(!reportOnly){
    const eventQuery=new URLSearchParams(base);if(event)eventQuery.set('event_type',event);if(staff)eventQuery.set('status',status||'all');
    jobs.push(['summary',`/analytics/summary?${base}`]);
    if(page==='Overview')jobs.push(['latest',`/weather/latest?${new URLSearchParams({kind:'observation',...(location?{location_id:location}:{})})}`],['map',`/analytics/locations?${new URLSearchParams(windowRange)}`]);
    if(page==='Overview'||page==='Analytics')jobs.push(['events',`/analytics/events?${eventQuery}&group_by=event_type`]);
    if(page==='Analytics')jobs.push(['days',`/analytics/events?${eventQuery}&group_by=day`]);
  }
  const outcomes=await Promise.allSettled(jobs.map(([,path])=>request(path,{signal:active.signal})));
  if(active.signal.aborted||generation!==loadGeneration)return;
  outcomes.forEach((outcome,index)=>{
    const [name,path]=jobs[index];
    if(outcome.status==='rejected'){
      const problem=outcome.reason;if(problem.name==='AbortError')return;problem.path=path;sectionErrors[name]=problem;
      if(name==='reports')error=problem;else if(name==='locations')locationError=problem;else if(name==='summary')summaryState='error';else if(name==='latest')latestState='error';else if(name==='events')eventState='error';else if(name==='days')dayState='error';else if(name==='map')mapState='error';return;
    }
    const data=outcome.value;
    if(name==='reports'){reports=data.items;reportPage={total:data.total,limit:data.limit,offset:data.offset};offset=data.offset;}
    else if(name==='locations'){locations=data.items;locationError=null;}
    else if(name==='summary'){summary=data;summaryState='success';}
    else if(name==='latest'){latest=data;latestState='success';}
    else if(name==='events'){eventData=data;eventState='success';}
    else if(name==='days'){dayData=data;dayState='success';}
    else if(name==='map'){mapData=data;mapState='success';}
  });
  loading=false;if(!error&&reportPage.total>0&&offset>=reportPage.total){offset=Math.floor((reportPage.total-1)/reportPage.limit)*reportPage.limit;load({reportOnly:true,focusId});return;}if(!error)lastSync=new Date();renderDashboard({focusId});
}
function loadSources(){const root=$('#source-content');if(root)renderSources(root,{role,time});}
async function boot(){
  const generation=++sessionGeneration;restoreController?.abort();restoreController=new AbortController();
  restoring=true;restoreFailed=false;sessionNotice='';render();
  let saved;try{saved=JSON.parse(sessionStorage.getItem(sessionKey)||'null');}catch{/* Corrupt or unavailable storage starts a public session. */}
  try{
    if(saved?.access_token&&Number.isFinite(saved.expires_at)){
      if(saved.expires_at<=Date.now()){window.dispatchEvent(new Event('session-expired'));}
      else{setToken(saved.access_token);const user=await request('/auth/me',{signal:restoreController.signal});if(generation!==sessionGeneration)return;if(!['reviewer','admin'].includes(user.role))throw Object.assign(new Error('Not permitted.'),{status:403});staff=true;role=user.role;expiresAt=saved.expires_at;armExpiry();}
    }
  }catch(problem){if(problem.name==='AbortError'||generation!==sessionGeneration)return;if(problem.status!==401){setToken(null);staff=false;role=null;expiresAt=null;restoreFailed=problem.status!==403;sessionNotice=errorMessage(problem);if(problem.status===403){clearSession();render();load();}}}
  finally{if(generation===sessionGeneration){restoring=false;render();load();}}
}
setInterval(updateExpiry,1000);
window.addEventListener('monsoon-motion-change',()=>render());
window.addEventListener('session-expired',()=>{clearSession();if(!loginOpen){page='Settings';render();login();}sessionNotice='Session expired. Please sign in again.';toast(sessionNotice);});installAccessibility();boot();setInterval(()=>{if(!document.hidden&&!$('#detail').open&&page!=='Settings'&&page!=='Staff access'&&page!=='Data sources'&&!featurePages.includes(page))load();},30000);
